WITH flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM transactions), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT island_id, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, COUNT(*) AS event_count, PERCENTILE_APPROX(island_id, 0.9) AS island_id_p90 FROM sessions_transactions GROUP BY 1 HAVING num_txn_types >= 1 ORDER BY island_id DESC;
